"""Generate the freestanding contract view from the one companion registry."""
import argparse,json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def generate(check=False):
 source=ROOT/'contracts/companion-v1.json';contract=json.loads(source.read_text());parameters=contract['parameters'];names=['filmId',*parameters]
 lines=['/* Generated by scripts/generate_companion_registry.py. Do not edit. */','#ifndef M10V_COMPANION_GENERATED_CONTRACT_H','#define M10V_COMPANION_GENERATED_CONTRACT_H','#include <stdint.h>',f'#define M10V_FIELD_COUNT {len(names)}u',f'#define M10V_CONTRACT_SHA256 "{hashlib.sha256(source.read_bytes()).hexdigest()}"','enum {'+','.join('M10V_FIELD_'+name.upper() for name in names)+'};', 'static const char *const m10v_field_names[M10V_FIELD_COUNT]={'+','.join(json.dumps(n) for n in names)+'};']
 lines+=['static inline unsigned m10v_field_max(unsigned field,unsigned film){switch(field){case M10V_FIELD_FILMID:return 321;']
 for key,spec in parameters.items():
  lines.append('case M10V_FIELD_'+key.upper()+':'+''.join(f'if(film=={film})return {limit};' for film,limit in spec.get('overrides',{}).items())+f'return {spec["max"]};')
 lines+=['default:return 0;}}','static inline int m10v_field_supported(unsigned field,unsigned film){if(!film||film>321||field>=M10V_FIELD_COUNT)return 0;switch(field){']
 for key,spec in parameters.items():
  allowed=spec.get('filmIds');excluded=spec.get('excludeFilmIds')
  if allowed:lines.append('case M10V_FIELD_'+key.upper()+':return '+'||'.join(f'film=={n}' for n in allowed)+';')
  elif excluded:lines.append('case M10V_FIELD_'+key.upper()+':return '+'&&'.join(f'film!={n}' for n in excluded)+';')
 lines+=['default:return 1;}}', '#define M10V_PARAMETERS_JSON '+json.dumps(json.dumps(parameters,separators=(',',':'),ensure_ascii=False),ensure_ascii=False), '#define M10V_LIMITS_JSON '+json.dumps(json.dumps(contract['limits'],separators=(',',':')),ensure_ascii=False), '#endif','']
 result='\n'.join(lines);output=ROOT/'native/companion/generated_contract.h'
 if check:
  if not output.exists() or output.read_text()!=result:raise ValueError('companion generated registry is stale')
 else:output.write_text(result)
if __name__=='__main__':
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');generate(parser.parse_args().check)
